@Component("payrollItem-handler")
@ProcessingGroup("payrollItem-processing-group")
public class PayrollItemEventHandler {
	
	// core constructor
	PayrollItemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePayrollItemEvent
     */
    @EventHandler
    public void handle( CreatePayrollItemEvent event) {
        entityManager.persist(new PayrollItem(event.getPayrollItemId(), event.getAmount(), event.getTaxable(), event.getPayrollRun(), event.getEmployee(), event.getItemType()));
    }

    /*
     * @param	event UpdatePayrollItemEvent
     */
    @EventHandler
    public PayrollItem handle( UpdatePayrollItemEvent event) {
    	entityManager.merge(new PayrollItem(event.getPayrollItemId(), event.getAmount(), event.getTaxable(), event.getPayrollRun(), event.getEmployee(), event.getItemType()));
    }
    
    /*
     * @param	event DeletePayrollItemEvent
     */
    @EventHandler
    public void on( DeletePayrollItemEvent event) {
    	PayrollItem entity = new PayrollItem();
   
    	// ------------------------------------------
    	// apply the PayrollItemId
    	// ------------------------------------------
    	entity.setPayrollItemId( event.getPayrollItemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PayrollItemRepository payrollItemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PayrollItemEventHandler.class.getName());

}
